package com.mayushi.trailsense

internal fun RatingExplanation(label: String): String? = when(label) {
    "Общая тяжесть маршрута" -> "Насколько труден сам маршрут: длина, набор высоты и препятствия. Помогает сравнивать маршруты отдельно от твоего состояния в этот день."
    "Общая нагрузка" -> "Сколько сил потребовал этот поход лично у тебя. В анализе рассматривается вместе со сном, темпом и рюкзаком."
    "Сложность подъёма" -> "Насколько тяжело было подниматься. Это твоё ощущение, а не замена набора высоты или времени часов."
    "Спуск" -> "Насколько тяжёлым был спуск для ног и внимания. Пустая оценка сама по себе не означает, что спуска не было: при спуске в записи это неуказанная оценка. Отсутствие можно подтвердить лишь по надёжному профилю без спуска; неполные и неоднозначные данные остаются неизвестными. Старые пустые ответы не переосмысливаются."
    "Техничность" -> "Сколько внимания и навыка требовали камни, корни, крутые или скользкие участки. 1 — простой маршрут. Пусто — нет данных, а не отсутствие техничности."
    "Экспозиция" -> "Насколько открытыми и тревожными были участки у обрывов или на высоте. 1 — обычный маршрут без выраженной экспозиции. Пусто — нет данных. Это ощущение, не оценка безопасности тропы."
    "Как я оцениваю сон" -> "Твоё впечатление от качества сна. Рассматривается рядом с длительностью и ощущением отдыха; часы сами эту оценку не задают."
    else -> null
}
